using LastRail.Battle;
using Newtonsoft.Json.Linq;
namespace LastRail.Run {
 public sealed class BRouteBinding {
  public const string Version="operation.b-route.v1.20261005";
  readonly JObject original;public string AccountId=>(string)original["accountId"];public string RunId=>(string)original["runId"];public string Hash=>(string)original["packetHash"];public long MapRevision=>(long)original["mapRevision"];public BScoutGunnerNodeSnapshot NativeNode{get;}public bool CanStart=>false;
  BRouteBinding(JObject p,BScoutGunnerNodeSnapshot source){original=(JObject)p.DeepClone();NativeNode=source;}
  public JObject Capture()=>(JObject)original.DeepClone();
  internal static JObject Trust(JObject p)=>new JObject(new[]{"origin","nativeContextId","seedHash","sourceHash","nodeId","visitDepth","priorSourceHash"}.Select(k=>new JProperty(k,p[k].DeepClone())));
  public static BRouteBinding Read(string json,string independentHash,string account,string run){
   var p=SafeTransitionWire.Parse(json);BDirectAttackInput.Fields(p,"version","accountId","runId","operationId","selectedRisk","runStatus","bindingHash","startSnapshotHash","mapRevision","phase","holdIds","currentNode","pendingNode","pendingEdgeId","nativeContextId","departurePinHash","originalNativeOrigin","nativeNodeSource","nodeSourceStatus","canStart","originalRuntimeVerifierRequired","packetHash");
   SafeTransitionWire.Pin(p,"packetHash",independentHash);if((string)p["version"]!=Version||SafeTransitionWire.Id(p,"accountId")!=account||SafeTransitionWire.Id(p,"runId")!=run||!new[]{"I","II","III","IV","V"}.Contains((string)p["selectedRisk"]))throw new ArgumentException("b_route_identity_version_conflict");SafeTransitionWire.Id(p,"operationId");SafeTransitionWire.Id(p,"runStatus");BDirectAttackInput.Nat(p,"mapRevision",1);SafeTransitionWire.Ids(p["holdIds"]);SafeTransitionWire.Boolean(p,"canStart",false);SafeTransitionWire.Boolean(p,"originalRuntimeVerifierRequired",true);
   foreach(var key in new[]{"bindingHash","startSnapshotHash"})RequireHash(p[key]);if(!new[]{"READY","TRAVELLING","ACTIVE","FINAL_NODE_COMPLETE"}.Contains((string)p["phase"]))throw new ArgumentException("b_route_phase_invalid");
   Node(p["currentNode"]);Node(p["pendingNode"]);bool travelling=(string)p["phase"]=="TRAVELLING";if(travelling!=(p["pendingEdgeId"].Type!=JTokenType.Null)||travelling!=(p["pendingNode"].Type!=JTokenType.Null))throw new ArgumentException("b_route_pending_node_conflict");if(travelling)SafeTransitionWire.Id(p,"pendingEdgeId");
   if(p["nativeContextId"].Type==JTokenType.Null){if(p["departurePinHash"].Type!=JTokenType.Null||p["originalNativeOrigin"].Type!=JTokenType.Null||p["nativeNodeSource"].Type!=JTokenType.Null)throw new ArgumentException("b_route_legacy_pin_conflict");}
   else{if(SafeTransitionWire.Id(p,"nativeContextId")==run)throw new ArgumentException("b_route_native_context_conflict");RequireHash(p["departurePinHash"]);var origin=(JObject)p["originalNativeOrigin"];RunWaveManifestReader.DepartureOrigin(origin);if((string)origin["accountId"]!=account||(string)origin["runId"]!=run||!JToken.DeepEquals(origin["operationId"],p["operationId"])||!JToken.DeepEquals(origin["selectedRisk"],p["selectedRisk"]))throw new ArgumentException("b_route_native_origin_conflict");}
   BScoutGunnerNodeSnapshot native=null;
   if(p["nativeNodeSource"].Type!=JTokenType.Null){var raw=(JObject)p["nativeNodeSource"];native=BScoutGunnerNodeSnapshot.Read(raw,Trust(raw));var active=p["pendingNode"].Type!=JTokenType.Null?p["pendingNode"]:p["currentNode"];if(active.Type==JTokenType.Null||!JToken.DeepEquals(raw["origin"],p["originalNativeOrigin"])||!JToken.DeepEquals(raw["nativeContextId"],p["nativeContextId"])||!JToken.DeepEquals(raw["nodeId"],active["nodeId"])||!JToken.DeepEquals(raw["visitDepth"],active["visitDepth"])||(string)p["nodeSourceStatus"]!="ORIGINAL_PINNED_NODE_SOURCE")throw new ArgumentException("b_route_native_node_conflict");}
   else if((string)p["nodeSourceStatus"]!="ORIGINAL_NODE_REFS_ONLY")throw new ArgumentException("b_route_native_source_status_conflict");
