  }
  internal void RequireOriginalDeparture(BRouteBinding other){foreach(var key in new[]{"accountId","runId","operationId","selectedRisk","bindingHash","startSnapshotHash","nativeContextId","departurePinHash","originalNativeOrigin"})if(!JToken.DeepEquals(original[key],other.original[key]))throw new ArgumentException("b_route_original_departure_changed");}
  internal void RequireSameDeparture(BRouteBinding other){RequireOriginalDeparture(other);if(other.MapRevision<MapRevision)throw new ArgumentException("b_route_map_revision_regressed");if(other.MapRevision==MapRevision&&!JToken.DeepEquals(original,other.original))throw new ArgumentException("b_route_same_revision_conflict");}
  static void RequireHash(JToken p){if(p?.Type!=JTokenType.String||!Regex.IsMatch((string)p,"^[a-f0-9]{64}$"))throw new ArgumentException("b_route_hash_invalid");}
  static void Node(JToken t){if(t.Type==JTokenType.Null)return;var n=(JObject)t;BDirectAttackInput.Fields(n,"nodeId","visitDepth","eventKind","publicInfo","encounterProfileRef","rewardPlanRef","encounterVersion","encounterDefinitionHash","encounterDefinition","completedWaveContract");foreach(var key in new[]{"nodeId","eventKind","encounterProfileRef","rewardPlanRef","encounterVersion"})SafeTransitionWire.Id(n,key);BDirectAttackInput.Nat(n,"visitDepth",1,12);RequireHash(n["encounterDefinitionHash"]);if(!(n["encounterDefinition"] is JObject)||SafeTransitionWire.Digest(n["encounterDefinition"])!=(string)n["encounterDefinitionHash"])throw new ArgumentException("b_route_encounter_hash_conflict");if(!(n["publicInfo"] is JObject))throw new ArgumentException("b_route_public_info_invalid");var w=(JObject)n["completedWaveContract"];BDirectAttackInput.Fields(w,"nodeId","waves","originalContractVersion");if(!JToken.DeepEquals(w["nodeId"],n["nodeId"]))throw new ArgumentException("b_route_wave_node_conflict");if(w["waves"].Type!=JTokenType.Null)BDirectAttackInput.Nat(w,"waves",0,128);if(w["originalContractVersion"].Type!=JTokenType.Null)SafeTransitionWire.Id(w,"originalContractVersion");}
 }
}
